const j=$input.first().json;
const game_title=String(j.game_title||'').trim();if(!game_title)throw Error('game_title is required');
const target=Number(j.target_video_duration_sec||90);if(!Number.isFinite(target)||target<15||target>600)throw Error('Review duration must be 15â€“600 seconds');
const language=String(j.language||'English');
return [{json:{...j,game_title,review_topic:String(j.review_topic||'A balanced review: distinctive strengths, limitations, and who should play'),language,target_video_duration_sec:target,voice:String(j.voice||'cedar'),file_slug:game_title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')+'-review-'+$execution.id,word_target:Math.round(target*(/persian|farsi|ÙØ§Ø±Ø³ÛŒ/i.test(language)?1.5:2.25)),review_only:j.review_only===true,attempt_budgets:{research_search:2,script:1,tts:1,transcription:1,render:1},source_policy:'official_first',source_audio_muted:true}}];

const j=$input.first().json;
const mood=String((j.review&&j.review.music&&j.review.music.mood)||'').toLowerCase();
const profiles=[
 {test:/metal|industrial|aggressive|brutal|combat|heavy/,directive:'Deliver with urgent, confident intensity. Slightly quicker pacing on action beats, clipped emphasis on key verbs, but still clearly articulated, not shouted.'},
 {test:/horror|dread|dark|tension|tense|ominous|eerie|haunting|restrained|survival/,directive:'Speak in a hushed, measured, restrained tone with a lingering sense of unease, like a quiet documentary narrator discussing something troubling beneath the surface. Slow down slightly on emotionally weighted words. Allow real pauses between clauses, do not rush. Avoid enthusiasm or upbeat energy.'},
 {test:/melancholic|somber|sad|emotional|narrative|tragic|reflective|mournful|quiet/,directive:'Speak gently and reflectively, with soft emphasis and unhurried pacing, as if recounting something bittersweet.'},
 {test:/adventurous|heroic|upbeat|hopeful|triumphant|epic|orchestral/,directive:'Speak with warm, confident energy and a sense of forward momentum, while staying conversational, not announcer-like.'},
];
const match=profiles.find(p=>p.test.test(mood));
const narration_style=(match?match.directive:'Measured conversational review delivery, not fast or dramatic.');
return [{json:{...j,narration_style}}];

const render = $('Parse Render Result').item.json;
const qc = $json;
return [{ json: { ...render, qc_report: qc, qc_retry_performed: false } }];

const fs = require('fs');
const render = $json;
const edlPath = render.edit_decision_list;
let edl = { shots: [] };
try { edl = JSON.parse(fs.readFileSync(edlPath, 'utf8')); } catch (e) { edl = { shots: [] }; }
const shots = Array.isArray(edl.shots) ? edl.shots : [];
const issues = (render.qc_report && render.qc_report.issues) || [];
const excludedPaths = new Set();
for (const issue of issues) {
  if (issue.severity !== 'high' && issue.severity !== 'medium') continue;
  const t = Number(issue.timestamp_sec);
  if (!Number.isFinite(t)) continue;
  for (const shot of shots) {
    const start = Number(shot.timeline_start_sec);
    const dur = Number(shot.duration);
    if (Number.isFinite(start) && Number.isFinite(dur) && t >= start - 0.5 && t <= start + dur + 0.5 && shot.path) {
      excludedPaths.add(shot.path);
    }
  }
}
return [{ json: { ...render, excluded_clip_paths: [...excludedPaths] } }];

const fs = require('fs');
const render = $json;
const originalManifestPath = render.work_dir ? render.work_dir.replace('/review-pipeline/renders/', '/review-pipeline/runs/') + '.json' : null;
let manifest = null;
if (originalManifestPath && fs.existsSync(originalManifestPath)) {
  manifest = JSON.parse(fs.readFileSync(originalManifestPath, 'utf8'));
} else {
  return [{ json: { ...render, retry_possible: false, retry_skip_reason: 'original_manifest_not_found' } }];
}
const newSlug = manifest.file_slug + '-qcretry';
manifest.file_slug = newSlug;
manifest.excluded_clip_paths = render.excluded_clip_paths || [];
const newManifestPath = '/home/node/.n8n-files/review-pipeline/runs/' + newSlug + '.json';
fs.writeFileSync(newManifestPath, JSON.stringify(manifest));
return [{ json: { ...render, retry_possible: true, retry_manifest_path: newManifestPath, retry_file_slug: newSlug } }];

const render = $('Parse Retry Render Result').item.json;
const qc = $json;
return [{ json: { ...render, qc_report: qc, qc_retry_performed: true, qc_pre_retry_issues: $('Merge QC Into Result').item.json.qc_report.issues } }];
